	local TOLERANCE = 0.05 -- Margin of error for physics/animations

	local heartbeatConnection = nil
	local characterAddedConnection = nil
	local baselineSizes = {}

	-- Function to cache your character's natural sizes
	local function cacheBaseline(character)
		table.clear(baselineSizes)
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("BasePart") then
				baselineSizes[child.Name] = child.Size
			end
		end
	end

	-- Safely disconnects the frame-by-frame loop without breaking respawn tracking
	local function stopHeartbeat()
		if heartbeatConnection then
			heartbeatConnection:Disconnect()
			heartbeatConnection = nil
		end
	end

	-- Completely turns off everything when the button is toggled off
	local function resetAllConnections()
		stopHeartbeat()
		if characterAddedConnection then
			characterAddedConnection:Disconnect()
			characterAddedConnection = nil
		end
	end

	-- Starts monitoring your character size efficiently
	local function startMonitoring(character)
		if not character then return end
		local humanoid = character:WaitForChild("Humanoid", 5)
		if not humanoid then return end

		-- Cache your actual spawn sizes
		cacheBaseline(character)

		-- Disconnect any old scan loop before making a new one
		stopHeartbeat()

		-- Efficient single-loop Heartbeat scan
		heartbeatConnection = RunService.Heartbeat:Connect(function()
			if not character or not character.Parent or humanoid.Health <= 0 then
				stopHeartbeat() -- Only stop the heartbeat loop on death, don't kill respawn listener
				return
			end

			for partName, expectedSize in pairs(baselineSizes) do
				local part = character:FindFirstChild(partName)
				if part and part:IsA("BasePart") then
					local sizeDifference = (part.Size - expectedSize).Magnitude
					if sizeDifference > TOLERANCE then
						-- Detection triggered: Kill the local player safely
						stopHeartbeat()
						task.wait(0.1)
						humanoid.Health = 0
						break
					end
				end
			end
		end)
	end

	-- Toggle button logic
	btn.MouseButton1Click:Connect(function()
		offon = not offon

		if offon then
			-- Turn ON: Start monitoring current character
			if LocalPlayer.Character then
				startMonitoring(LocalPlayer.Character)
			end

			-- Setup clean listener for next spawns (This now stays alive after death)
			if not characterAddedConnection then
				characterAddedConnection = LocalPlayer.CharacterAdded:Connect(function(newCharacter)
					task.wait(0.5) -- Give character a brief moment to assemble
					if offon then
						startMonitoring(newCharacter)
					end
				end)
			end
		else
			-- Turn OFF: Safely clear everything from memory
			resetAllConnections()
		end
	end)

end;
